#!/usr/bin/env node

const path = require('path');
const fs = require('fs');

console.log('Patch for OMO - CLI Tool');
console.log('========================');
console.log('');

const args = process.argv.slice(2);

if (args.length === 0) {
  console.log('Usage: patch-for-omo <command> [options]');
  console.log('');
  console.log('Commands:');
  console.log('  init        Initialize plugin configuration');
  console.log('  validate    Validate current configuration');
  console.log('  version     Show plugin version');
  console.log('  help        Show this help message');
  console.log('');
  console.log('Examples:');
  console.log('  patch-for-omo init');
  console.log('  patch-for-omo validate');
  process.exit(0);
}

const command = args[0];

switch (command) {
  case 'version':
    const pkgPath = path.join(__dirname, '..', 'package.json');
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    console.log(`patch-for-omo v${pkg.version}`);
    break;

  case 'init':
    const configPath = path.join(process.cwd(), '.opencode', 'oh-my-opencode.json');
    const defaultConfig = {
      "plugins": ["patch-for-omo"],
      "patch-for-omo": {
        "receptionist": {
          "model": "bailian-coding-plan/glm-5",
          "enabled": true
        },
        "secretary": {
          "model": "zishuijin/grok-4.1-fast",
          "enabled": true,
          "monitoring_interval": 30000,
          "event_driven": true
        },
        "sisyphus_isolation": {
          "enabled": true,
          "activation_conditions": [
            "secretary_report_received",
            "all_background_tasks_completed",
            "context_ready"
          ]
        }
      }
    };

    const configDir = path.dirname(configPath);
    if (!fs.existsSync(configDir)) {
      fs.mkdirSync(configDir, { recursive: true });
    }

    if (fs.existsSync(configPath)) {
      console.log('Configuration file already exists:', configPath);
      console.log('Please manually add the patch-for-omo configuration.');
    } else {
      fs.writeFileSync(configPath, JSON.stringify(defaultConfig, null, 2));
      console.log('Configuration file created:', configPath);
    }
    break;

  case 'validate':
    console.log('Validating configuration...');
    try {
      const configPath = path.join(process.cwd(), '.opencode', 'oh-my-opencode.json');
      if (!fs.existsSync(configPath)) {
        console.log('No configuration file found.');
        console.log('Run "patch-for-omo init" to create one.');
        process.exit(1);
      }
      const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));

      if (!config.plugins || !config.plugins.includes('patch-for-omo')) {
        console.log('Warning: patch-for-omo is not in the plugins list.');
      }

      if (!config['patch-for-omo']) {
        console.log('Warning: patch-for-omo configuration is missing.');
      } else {
        console.log('Configuration is valid.');
        console.log('  Receptionist model:', config['patch-for-omo'].receptionist?.model || 'default');
        console.log('  Secretary model:', config['patch-for-omo'].secretary?.model || 'default');
        console.log('  Sisyphus isolation:', config['patch-for-omo'].sisyphus_isolation?.enabled ? 'enabled' : 'disabled');
      }
    } catch (error) {
      console.log('Configuration validation failed:', error.message);
      process.exit(1);
    }
    break;

  case 'help':
  default:
    console.log('For more information, visit: https://github.com/yourusername/patch-for-omo');
    break;
}

import { logger } from './shared/logger.js';
import { PLUGIN_NAME, PLUGIN_VERSION } from './shared/constants.js';
import { createChatMessageHook } from './hooks/chat-message-hook.js';
export class PatchForOMOPlugin {
    pluginInput;
    constructor() {
        logger.info(`Plugin initialized: ${PLUGIN_NAME} v${PLUGIN_VERSION}`);
    }
    async initialize(pluginInput) {
        this.pluginInput = pluginInput;
        logger.info('Plugin initialized with OpenCode context', {
            directory: pluginInput.directory,
        });
    }
    getHooks() {
        return {
            'chat.message': createChatMessageHook(this.pluginInput, null),
        };
    }
    getVersion() {
        return PLUGIN_VERSION;
    }
    getName() {
        return PLUGIN_NAME;
    }
}
export function createPlugin() {
    return new PatchForOMOPlugin();
}
const pluginFactory = async (input) => {
    const plugin = new PatchForOMOPlugin();
    await plugin.initialize(input);
    return plugin.getHooks();
};
export default pluginFactory;
export { logger, PLUGIN_NAME, PLUGIN_VERSION, };
